 1 """
 2 OOS Numbering Service
 3 Generates PP-OOS-YYYY-NNNN identifiers per QCSOP 019-A03.
 4 Uses atomic DB sequence for race-free ID generation.
 5 """
 6 
 7 from sqlalchemy import text
 8 from sqlalchemy.ext.asyncio import AsyncSession
 9 from datetime import datetime
10 
11 
12 async def next_oos_number(db: AsyncSession) -> str:
13     """
14     Generate next OOS identifier: PP-OOS-YYYY-NNNN
15     
16     Sequence: oos_id_seq (created via Alembic)
17     Format: PP-OOS-YYYY-NNNN
18     
19     Args:
20         db: Async database session
21     
22     Returns:
23         Formatted OOS ID string
24     
25     Raises:
26         ValueError: If sequence is exhausted (max 9999 per year)
27     """
28     result = await db.execute(text("SELECT nextval('oos_id_seq')"))
29     seq = result.scalar_one()
30     if seq > 9999:
31         raise ValueError("OOS ID sequence exhausted for this year (max 9999)")
32     year = datetime.utcnow().year
33     return f"PP-OOS-{year}-{seq:04d}"
