 54     def get_stage_order(cls, status: str) -> int:
 55         """Return numeric stage order for sequential validation (0-7)."""
 56         stage_map = {
 57             cls.INITIATED.value: 0,
 58             cls.DRAFT.value: 1,
 59             cls.QC_REVIEW.value: 2,
 60             cls.QA_APPROVED.value: 3,
 61             cls.NUMBERED.value: 4,
 62             cls.TRAINED.value: 5,
 63             cls.ACTIVE.value: 6,
 64             cls.UNDER_CHANGE.value: 7,
 65         }
