116 class Chemotype(StrEnum):
117     """Cannabis chemotype classification per P1-E3.
118     
119     THC-dominant: THC ≥ 5.0%, CBD ≤ 1.0%
120     THC-CBD-intermediate: THC 1.0-5.0%, CBD ≥ 1.0%, ratio 0.2-5.0
121     CBD-dominant: THC ≤ 1.0%, CBD ≥ 5.0%
122     """
123     THC_DOMINANT = "THC_DOMINANT"
124     THC_CBD_INTERMEDIATE = "THC_CBD_INTERMEDIATE"
125     CBD_DOMINANT = "CBD_DOMINANT"
126 
127     @classmethod
128     def validate_from_percentages(cls, thc_pct: float, cbd_pct: float) -> "Chemotype":
129         """Determine chemotype from THC and CBD percentages."""
130         ratio = thc_pct / cbd_pct if cbd_pct > 0 else float('inf')
131         
132         if thc_pct >= 5.0 and cbd_pct <= 1.0:
133             return cls.THC_DOMINANT
134         elif 1.0 <= thc_pct <= 5.0 and cbd_pct >= 1.0 and 0.2 <= ratio <= 5.0:
135             return cls.THC_CBD_INTERMEDIATE
136         elif thc_pct <= 1.0 and cbd_pct >= 5.0:
137             return cls.CBD_DOMINANT
138         else:
139             raise ValueError(
140                 f"Chemotype validation failed: THC={thc_pct}%, CBD={cbd_pct}% "
141                 f"does not meet any chemotype criteria. "
142                 "THC-dominant requires THC≥5.0% and CBD≤1.0%; "
143                 "Intermediate requires THC 1.0-5.0%, CBD≥1.0%, ratio 0.2-5.0; "
144                 "CBD-dominant requires THC≤1.0% and CBD≥5.0%."
145             )
